<script lang="ts">
 import Icon from '$lib/components/Icon.svelte';import {detect,frameworks,type Detection} from '$lib/detection/model.js';import type {Tree} from '$lib/files/model.js';
 export let tree:Tree;export let config:Detection;export let onChange:(value:Detection)=>void=()=>{};function update<K extends keyof Detection>(key:K,value:Detection[K]){config={...config,[key]:value};onChange(config);}let rootError='';let extraKey='';let keyError='';$: roots=['.',...Object.keys(tree).filter(p=>p.startsWith('app/')&&tree[p].kind==='folder').map(p=>p.slice(4))];
 function changeRoot(root:string){try{config=detect(tree,root);onChange(config);rootError='';}catch(e){rootError=e instanceof Error?e.message:'Invalid source root.';}}
 function addKey(){const key=extraKey.trim();if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)||config.environmentKeys.includes(key)||config.environmentKeys.length>=50){keyError='Enter a unique environment variable name.';return;}update('environmentKeys',[...config.environmentKeys,key]);extraKey='';keyError='';}
</script>
<div class="stack"><section class="well stack"><div class="row between wrap"><div class="row"><span class="icon-box"><Icon name={config.confidence==='Detected'?'Check':'Code'}/></span><div><strong>{config.framework}</strong><small style="display:block">{config.reason}</small></div></div><span class={'pill '+(config.confidence==='Detected'?'success':'warning')}>{config.confidence}</span></div>{#if config.candidates.length>1}<label class="field">Application source root<select value={config.root} on:change={(e)=>changeRoot(e.currentTarget.value)}><option value=".">. · Root directory</option>{#each config.candidates.filter(root=>root!=='.') as root}<option value={root}>{root}</option>{/each}</select></label>{/if}<small>Inspection only. Detected commands will not run in this browser.</small></section>{#if config.databaseHint}<div class="callout"><strong>Your application may need a database.</strong><p>Connect an existing database or create one later in the project. No database is required to save this draft.</p></div>{/if}<details class="advanced"><summary>Deployment settings <small>Optional</small></summary><div class="stack"><div class="grid2"><label class="field">Application type<select value={config.framework} on:change={(e)=>update('framework',e.currentTarget.value)}>{#each frameworks as f}<option>{f}</option>{/each}</select></label><label class="field">Root directory<select value={config.root} on:change={(e)=>changeRoot(e.currentTarget.value)}>{#each roots as root}<option value={root}>{root}</option>{/each}</select></label></div>{#if rootError}<p class="error" role="alert">{rootError}</p>{/if}<label class="field">Install command<input value={config.install} on:input={(e)=>update('install',e.currentTarget.value)} maxlength="500" placeholder="Optional"/></label><label class="field">Build command<input value={config.build} on:input={(e)=>update('build',e.currentTarget.value)} maxlength="500" placeholder="Optional"/></label><label class="field">Start command<input value={config.start} on:input={(e)=>update('start',e.currentTarget.value)} maxlength="500" placeholder="Optional"/></label><label class="field">Output directory<input value={config.output} on:input={(e)=>update('output',e.currentTarget.value)} maxlength="500" placeholder="Optional"/></label><div class="grid3"><label class="field">Internal port<input type="number" min="1" max="65535" value={config.port} on:input={(e)=>update('port',e.currentTarget.valueAsNumber)}/></label><label class="field">Memory (MiB)<input type="number" min="64" max="65536" value={config.ram} on:input={(e)=>update('ram',e.currentTarget.valueAsNumber)}/></label><label class="field">CPU (% of one core)<input type="number" min="1" max="100" value={config.cpu} on:input={(e)=>update('cpu',e.currentTarget.valueAsNumber)}/></label></div></div></details><details class="advanced"><summary>Environment variables <small>Optional</small></summary><div class="stack">{#each config.environmentKeys as key}<div class="setting-row"><span class="mono native-path">{key}</span><button type="button" class="btn secondary small" on:click={()=>update('environmentKeys',config.environmentKeys.filter(k=>k!==key))}>Remove</button></div>{/each}<div class="native-inline"><label class="field grow">Variable name<input bind:value={extraKey} placeholder="DATABASE_URL"/></label><button type="button" class="btn secondary" on:click={addKey}>Add variable</button></div>{#if keyError}<p class="error" role="alert">{keyError}</p>{/if}<small>Only variable names are retained. Do not enter real credentials.</small></div></details></div>
